CREATE OR REPLACE FUNCTION public.terminal_can(uid uuid, perm text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.terminal_is_admin(uid) OR public.has_terminal_permission(uid, perm::public.terminal_permission); $$;
REVOKE ALL ON FUNCTION public.terminal_can(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.terminal_can(uuid,text) TO authenticated,service_role;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['p2p_auto_reply_rules','p2p_merchant_schedules','p2p_auto_pay_settings','small_sales_config','small_buys_config'] LOOP EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I','authenticated_all_'||t,t); EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON public.%I TO authenticated',t); EXECUTE format('GRANT ALL ON public.%I TO service_role',t); END LOOP; END $$;
CREATE POLICY tau_reply_read ON public.p2p_auto_reply_rules FOR SELECT TO authenticated USING (public.has_terminal_access(auth.uid()));
CREATE POLICY tau_reply_insert ON public.p2p_auto_reply_rules FOR INSERT TO authenticated WITH CHECK (public.terminal_can(auth.uid(),'terminal_autoreply_manage'));
CREATE POLICY tau_reply_update ON public.p2p_auto_reply_rules FOR UPDATE TO authenticated USING (public.terminal_can(auth.uid(),'terminal_autoreply_manage') OR public.terminal_can(auth.uid(),'terminal_autoreply_toggle')) WITH CHECK (public.terminal_can(auth.uid(),'terminal_autoreply_manage') OR public.terminal_can(auth.uid(),'terminal_autoreply_toggle'));
CREATE POLICY tau_reply_delete ON public.p2p_auto_reply_rules FOR DELETE TO authenticated USING (public.terminal_can(auth.uid(),'terminal_destructive'));
CREATE POLICY tau_schedule_read ON public.p2p_merchant_schedules FOR SELECT TO authenticated USING (public.has_terminal_access(auth.uid()));
CREATE POLICY tau_schedule_insert ON public.p2p_merchant_schedules FOR INSERT TO authenticated WITH CHECK (public.terminal_can(auth.uid(),'terminal_autoreply_manage'));
CREATE POLICY tau_schedule_update ON public.p2p_merchant_schedules FOR UPDATE TO authenticated USING (public.terminal_can(auth.uid(),'terminal_autoreply_manage')) WITH CHECK (public.terminal_can(auth.uid(),'terminal_autoreply_manage'));
CREATE POLICY tau_schedule_delete ON public.p2p_merchant_schedules FOR DELETE TO authenticated USING (public.terminal_can(auth.uid(),'terminal_destructive'));
CREATE POLICY tau_pay_read ON public.p2p_auto_pay_settings FOR SELECT TO authenticated USING (public.has_terminal_access(auth.uid()));
CREATE POLICY tau_pay_insert ON public.p2p_auto_pay_settings FOR INSERT TO authenticated WITH CHECK (public.terminal_can(auth.uid(),'terminal_autopay_configure'));
CREATE POLICY tau_pay_update ON public.p2p_auto_pay_settings FOR UPDATE TO authenticated USING (public.terminal_can(auth.uid(),'terminal_autopay_toggle') OR public.terminal_can(auth.uid(),'terminal_autopay_configure')) WITH CHECK (public.terminal_can(auth.uid(),'terminal_autopay_toggle') OR public.terminal_can(auth.uid(),'terminal_autopay_configure'));
CREATE POLICY tau_pay_delete ON public.p2p_auto_pay_settings FOR DELETE TO authenticated USING (public.terminal_is_admin(auth.uid()));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['small_sales_config','small_buys_config'] LOOP EXECUTE format('CREATE POLICY tau_small_read ON public.%I FOR SELECT TO authenticated USING (true)',t); EXECUTE format('CREATE POLICY tau_small_insert ON public.%I FOR INSERT TO authenticated WITH CHECK (public.terminal_can(auth.uid(),''terminal_automation_manage''))',t); EXECUTE format('CREATE POLICY tau_small_update ON public.%I FOR UPDATE TO authenticated USING (public.terminal_can(auth.uid(),''terminal_automation_manage'')) WITH CHECK (public.terminal_can(auth.uid(),''terminal_automation_manage''))',t); EXECUTE format('CREATE POLICY tau_small_delete ON public.%I FOR DELETE TO authenticated USING (public.terminal_is_admin(auth.uid()))',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.tau_guard_reply_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR auth.role()='service_role' THEN RETURN NEW; END IF; IF NOT public.terminal_can(auth.uid(),'terminal_autoreply_manage') AND (to_jsonb(NEW)-ARRAY['is_active','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['is_active','updated_at']) THEN RAISE EXCEPTION 'Auto-reply Manage required to edit rule content' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
CREATE TRIGGER tau_reply_update_guard BEFORE UPDATE ON public.p2p_auto_reply_rules FOR EACH ROW EXECUTE FUNCTION public.tau_guard_reply_update();
CREATE OR REPLACE FUNCTION public.tau_guard_pay_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR auth.role()='service_role' THEN RETURN NEW; END IF; IF NEW.is_active IS DISTINCT FROM OLD.is_active AND NOT public.terminal_can(auth.uid(),'terminal_autopay_toggle') THEN RAISE EXCEPTION 'Auto-pay Toggle required' USING ERRCODE='42501'; END IF; IF (to_jsonb(NEW)-ARRAY['is_active','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['is_active','updated_at','updated_by']) AND NOT public.terminal_can(auth.uid(),'terminal_autopay_configure') THEN RAISE EXCEPTION 'Auto-pay Configure required to edit settings' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
CREATE TRIGGER tau_pay_update_guard BEFORE UPDATE ON public.p2p_auto_pay_settings FOR EACH ROW EXECUTE FUNCTION public.tau_guard_pay_update();
ALTER TABLE public.p2p_auto_pay_settings ADD CONSTRAINT tau_pay_minutes_check CHECK (minutes_before_expiry BETWEEN 1 AND 30);
ALTER TABLE public.p2p_merchant_schedules ADD COLUMN exchange_account_id uuid NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001', ADD CONSTRAINT tau_schedule_window_check CHECK (action='go_online' OR start_time<>end_time);
CREATE TABLE public.p2p_merchant_schedule_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),schedule_id uuid REFERENCES public.p2p_merchant_schedules(id) ON DELETE SET NULL,schedule_name text,exchange_account_id uuid,action text,occurrence_start timestamptz NOT NULL,occurrence_end timestamptz,outcome text CHECK (outcome IN ('started','ended_rest','skipped','failed','nothing_to_do')),message text,rest_timer_id uuid,created_at timestamptz DEFAULT now(),UNIQUE(schedule_id,occurrence_start));
GRANT SELECT ON public.p2p_merchant_schedule_runs TO authenticated;
GRANT ALL ON public.p2p_merchant_schedule_runs TO service_role;
ALTER TABLE public.p2p_merchant_schedule_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY tau_run_read ON public.p2p_merchant_schedule_runs FOR SELECT TO authenticated USING (public.has_terminal_access(auth.uid()));
CREATE POLICY tau_run_service ON public.p2p_merchant_schedule_runs FOR ALL TO service_role USING (true) WITH CHECK (true);
CREATE INDEX tau_schedule_runs_recent ON public.p2p_merchant_schedule_runs(schedule_id,created_at DESC);
ALTER TABLE public.ad_rest_timer ADD COLUMN source text NOT NULL DEFAULT 'manual', ADD COLUMN schedule_id uuid REFERENCES public.p2p_merchant_schedules(id) ON DELETE SET NULL, ADD COLUMN exchange_account_id uuid;
ALTER TABLE public.ad_pricing_rules ADD COLUMN last_manual_run_at timestamptz;
CREATE OR REPLACE FUNCTION public.tau_claim_manual_price_run(p_rule_id uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.ad_pricing_rules%ROWTYPE; BEGIN SELECT * INTO r FROM public.ad_pricing_rules WHERE id=p_rule_id FOR UPDATE; IF NOT FOUND THEN RETURN 'not_found'; END IF; IF NOT r.is_active THEN RETURN 'paused'; END IF; IF r.last_manual_run_at>clock_timestamp()-interval '60 seconds' THEN RETURN 'rate_limited'; END IF; UPDATE public.ad_pricing_rules SET last_manual_run_at=clock_timestamp() WHERE id=p_rule_id; RETURN 'claimed'; END $$;
REVOKE ALL ON FUNCTION public.tau_claim_manual_price_run(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.tau_claim_manual_price_run(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.tau_due_merchant_schedules() RETURNS SETOF public.p2p_merchant_schedules LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH clock AS (SELECT now() AS n,now() AT TIME ZONE 'Asia/Kolkata' AS local_now), windows AS (SELECT s.*, (d.day+s.start_time) AT TIME ZONE 'Asia/Kolkata' AS window_start,(d.day+s.end_time+CASE WHEN s.end_time<s.start_time THEN interval '1 day' ELSE interval '0 day' END) AT TIME ZONE 'Asia/Kolkata' AS window_end FROM public.p2p_merchant_schedules s CROSS JOIN clock c CROSS JOIN LATERAL (VALUES(c.local_now::date),(c.local_now::date-1)) d(day) WHERE s.is_active AND extract(dow FROM d.day)=s.day_of_week)
SELECT s FROM public.p2p_merchant_schedules s JOIN windows w ON w.id=s.id CROSS JOIN clock c WHERE w.window_start<=c.n AND ((w.action='go_online' AND c.n<w.window_start+interval '1 minute') OR (w.action<>'go_online' AND c.n<=w.window_end-interval '1 minute')) AND NOT EXISTS(SELECT 1 FROM public.p2p_merchant_schedule_runs r WHERE r.schedule_id=s.id AND r.occurrence_start=w.window_start);
$$;
REVOKE ALL ON FUNCTION public.tau_due_merchant_schedules() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.tau_due_merchant_schedules() TO service_role;